import {chromium} from 'playwright';
import assert from 'node:assert/strict';
import {createServer} from 'node:http';
import {readFile} from 'node:fs/promises';
const root=process.cwd()+'/test/';
const server=createServer(async(req,res)=>{try{const p=new URL(req.url,'http://localhost').pathname;const allowed={'/test/admin-recovery.html':'admin-recovery.html','/test/admin-recovery/reset.mjs':'admin-recovery/reset.mjs','/test/admin-recovery/client.mjs':'admin-recovery/client.mjs','/test/original.css':'original.css','/test/styles.css':'styles.css'};if(p==='/test/config.js'){res.setHeader('content-type','application/javascript');return res.end("window.ISPOVESTI_CONFIG={mode:'live-test',supabaseUrl:'https://abcdefghijklmnopqrst.supabase.co',publishableKey:'dummy'};");}if(!allowed[p]){res.statusCode=404;return res.end();}res.setHeader('content-type',p.endsWith('.mjs')?'application/javascript':p.endsWith('.css')?'text/css':'text/html');res.end(await readFile(root+allowed[p]));}catch{res.statusCode=500;res.end();}});
await new Promise(r=>server.listen(0,'127.0.0.1',r));const port=server.address().port;const browser=await chromium.launch({headless:true});
try{for(const viewport of [{width:390,height:844},{width:1366,height:768}]){const page=await browser.newPage({viewport});let calls=0,fail=false;await page.route('https://abcdefghijklmnopqrst.supabase.co/functions/v1/admin-recovery-test-api',async route=>{if(route.request().method()==='OPTIONS')return route.fulfill({status:204,headers:{'access-control-allow-origin':'*','access-control-allow-headers':'apikey,content-type','access-control-allow-methods':'POST,OPTIONS'}});calls++;await route.fulfill({status:fail?503:200,headers:{'content-type':'application/json','access-control-allow-origin':'*','access-control-allow-headers':'apikey,content-type','access-control-allow-methods':'POST,OPTIONS'},body:JSON.stringify(fail?{error:'Probna greška'}:{success:true,message:'Probna lozinka promijenjena'})});});const token='a'.repeat(43);await page.goto(`http://127.0.0.1:${port}/test/admin-recovery.html#token=${token}`);assert.equal(new URL(page.url()).hash,'');await page.fill('#new-password','Example-Password-123');await page.fill('#repeat-password','Example-Password-456');await page.click('button[type=submit]');assert.match(await page.locator('#recovery-status').innerText(),/ne podudaraju/);assert.equal(calls,0);await page.fill('#repeat-password','Example-Password-123');await page.click('button[type=submit]');await page.getByText('Probna lozinka promijenjena').waitFor();assert.equal(calls,1);assert.equal(await page.locator('#reset-form').isHidden(),true);assert.equal(await page.inputValue('#new-password'),'');await page.goto(`http://127.0.0.1:${port}/test/admin-recovery.html#token=bad`);assert.equal(await page.locator('#reset-form').isHidden(),true);fail=true;await page.goto('about:blank');await page.goto(`http://127.0.0.1:${port}/test/admin-recovery.html#token=${token}`);await page.fill('#new-password','Example-Password-123');await page.fill('#repeat-password','Example-Password-123');await page.click('button[type=submit]');await page.getByText(/Probna greška/).waitFor();assert.equal(await page.locator('#reset-form').isHidden(),true);assert.equal(await page.inputValue('#new-password'),'');await page.close();}console.log('PASS: actual recovery page on mobile and desktop; token removal, mismatch, mocked success and error.');}finally{await browser.close();server.close();}
